12	// Import the registry and contract *directly*, never the ../agents barrel: the
13	// barrel imports the Claude adapter, which imports this module — going through
14	// it would form an import cycle. registry.ts / contract.ts depend on neither.
15	import { agentRegistry } from '../agents/registry';
16	import { DEFAULT_AGENT_ID } from '../agents/contract';
17	import type { PermissionMode, TaskModel } from '@shared/types';
