81	/**
82	 * Per-task initial prompt to pass as `claude`'s positional argument when the
83	 * task's agent PTY is spawned. Used by the ports onboarding migrate path:
84	 * the full inlined setup-prompt body (see PortsSetupPrompt) is stashed here
85	 * before the renderer triggers the spawn, so CC auto-submits it as soon as
86	 * the trust-this-directory gate clears — no post-spawn keystroke injection
87	 * needed (which previously raced first-run gates and flashed visibly in the
88	 * input box).
89	 *
90	 * Single-use: consumed (and removed) by startDirectPty's first spawn. A
91	 * re-attach to an existing PTY is a no-op — the prompt only applies to the
92	 * very first claude process for the task. Consequence: if that first spawn
93	 * dies before the user accepts the trust gate, the prompt is gone and a
94	 * respawn starts a plain session (the ports TUI then surfaces its
95	 * 30-minute timeout). The consumption breadcrumb in the ports debug log is
96	 * the trail for diagnosing that.
97	 */
98	const pendingInitialPrompts = new Map<string, string>();
99	
100	export function setInitialPrompt(taskId: string, prompt: string): void {
101	  pendingInitialPrompts.set(taskId, prompt);
102	}
103	
104	function consumeInitialPrompt(taskId: string): string | undefined {
105	  const prompt = pendingInitialPrompts.get(taskId);
106	  if (prompt !== undefined) pendingInitialPrompts.delete(taskId);
107	  return prompt;
108	}
109	
110	/** Test/cleanup hook: drop a stashed prompt without spawning. */
111	export function discardInitialPrompt(taskId: string): void {
112	  pendingInitialPrompts.delete(taskId);
113	}
114	
115	// Custom environment variables passed to spawned Claude processes (set from renderer settings).
116	let claudeEnvVars: Record<string, string> = {};
117	
118	// When true, inherit the full parent process.env as a base instead of the minimal set.
119	let syncShellEnv = false;
120	
121	// When true, launch Claude sessions in ultracode (X-High reasoning + multi-agent
122	// workflow orchestration) via `--settings '{"ultracode":true}'`. ultracode is
123	// session-only and can't be set through CLAUDE_CODE_EFFORT_LEVEL or --effort, so
124	// it's applied per-spawn here rather than through the effort env var.
125	let ultracode = false;
126	
127	const RESERVED_ENV_KEYS = new Set([
128	  'PATH',
129	  'HOME',
130	  'USER',
131	  'TERM',
132	  'COLORTERM',
133	  'TERM_PROGRAM',
134	  'COLORFGBG',
135	  // Dash owns this — it points hooks at the live HookServer port. A user/ports
136	  // override would misroute or break the no-op-outside-Dash guard.
137	  'DASH_HOOK_PORT',
138	]);
139	
140	export function setCommitAttribution(value: string | undefined): void {
141	  setCommitAttributionValue(value);
142	  refreshActivePtyHooks();
143	}
144	
145	export interface RefreshFailure {
146	  settingsPath: string;
147	  error: string;
148	}
149	
150	export interface RefreshResult {
151	  failures: RefreshFailure[];
152	}
153	
154	/**
155	 * Rewrite settings.local.json for every active PTY. Claude Code re-reads
156	 * settings per tool call, so this flips hooks live. Returns per-task write
157	 * failures so callers (RTK toggle, attribution change) can surface a
158	 * "saved, but N tasks didn't pick it up" message instead of silently
159	 * returning success.
160	 */
161	export function refreshActivePtyHooks(): RefreshResult {
162	  const failures: RefreshFailure[] = [];
163	  for (const [id, rec] of ptys) {
164	    // Shell PTYs (terminal drawer) share cwd with the task PTY but don't run
165	    // Claude Code and aren't tracked by ActivityMonitor. Writing hook settings
166	    // for them clobbers the task's settings.local.json with `ptyId=shell:…`,
167	    // so every subsequent hook event lands in ActivityMonitor's no-op branch
168	    // and the task's activity dot freezes on whatever it was last showing.
169	    if (!rec.isDirectSpawn) continue;
170	    const result = writeHookSettings(rec.cwd, id);
171	    if (!result.ok) {
172	      failures.push({ settingsPath: result.settingsPath, error: result.error });
173	    }
174	  }
175	  return { failures };
176	}
