198	// Lazy-load node-pty to avoid native binding issues at startup
199	let ptyModule: typeof import('node-pty') | null = null;
200	let ptyLoadError: string | null = null;
201	function getPty() {
202	  if (ptyLoadError) {
203	    throw new Error(ptyLoadError);
204	  }
205	  if (!ptyModule) {
206	    try {
207	      ptyModule = require('node-pty');
208	    } catch (err) {
209	      ptyLoadError =
210	        `[native module] node-pty failed to load: ${String(err)}. ` +
211	        'Try rebuilding native modules: pnpm rebuild';
212	      throw new Error(ptyLoadError);
213	    }
214	  }
215	  return ptyModule!;
216	}
