218	import { createBannerFilter } from './bannerFilter';
219	import { remoteControlService } from './remoteControlService';
220	
221	/**
222	 * Build environment for direct CLI spawn.
223	 * When syncShellEnv is off (default), uses a minimal set for fast, predictable spawns.
224	 * When on, inherits the full parent process.env as a base.
225	 *
226	 * Exported so the Claude agent adapter (src/main/agents/claude) can delegate to
227	 * the exact same env builder the host used pre-extraction — the shared spawn
228	 * environment (PATH merge, per-task port env, DASH_HOOK_PORT, auth passthrough)
229	 * is host infrastructure, and delegating keeps the Claude spawn byte-identical.
230	 */
231	export function buildDirectEnv(isDark: boolean, cwd?: string): Record<string, string> {
232	  const isWin = process.platform === 'win32';
233	  const base: Record<string, string> = syncShellEnv
234	    ? Object.fromEntries(Object.entries(process.env).filter((e): e is [string, string] => !!e[1]))
235	    : {};
236	
237	  // rtk's rewrite output invokes the bare name `rtk`; when the binary is
238	  // Dash-managed (userData/bin), prepend that dir so the rewrite resolves.
239	  const rtkBinDir = RtkService.getManagedBinDirForPath();
240	  const pathSep = isWin ? ';' : ':';
241	  const basePath = process.env.PATH || '';
242	  const mergedPath = rtkBinDir ? prependUnique(rtkBinDir, basePath, pathSep) : basePath;
243	
244	  const env: Record<string, string> = {
245	    ...base,
246	    TERM_PROGRAM: 'dash',
247	    HOME: os.homedir(),
248	    PATH: mergedPath,
249	    // Tell CLI apps about terminal background (rxvt convention)
250	    // Format: "fg;bg" where higher values = lighter colors
251	    COLORFGBG: isDark ? '15;0' : '0;15',
252	  };
253	
254	  if (isWin) {
255	    // Windows requires system env vars for DNS, credential storage, and Node.js.
256	    // Includes both casings of SystemRoot since some processes look for one or
257	    // the other (cmd.exe sets SystemRoot, PowerShell sees SYSTEMROOT in env).
258	    env.USERNAME = process.env.USERNAME || os.userInfo().username;
259	    const winVars = [
260	      'APPDATA',
261	      'LOCALAPPDATA',
262	      'USERPROFILE',
263	      'TEMP',
264	      'TMP',
265	      'SystemRoot',
266	      'SYSTEMROOT',
267	      'SystemDrive',
268	      'WINDIR',
269	      'COMSPEC',
270	      'PATHEXT',
271	      'COMPUTERNAME',
272	      'USERDOMAIN',
273	      'ProgramFiles',
274	    ];
275	    for (const key of winVars) {
276	      if (process.env[key]) env[key] = process.env[key]!;
277	    }
278	  } else {
279	    env.TERM = 'xterm-256color';
280	    env.COLORTERM = 'truecolor';
281	    env.USER = os.userInfo().username;
282	  }
283	
284	  if (!syncShellEnv) {
285	    // Auth passthrough — only needed when not inheriting full env
286	    const authVars = [
287	      'ANTHROPIC_API_KEY',
288	      'GH_TOKEN',
289	      'GITHUB_TOKEN',
290	      'HTTP_PROXY',
291	      'HTTPS_PROXY',
292	      'NO_PROXY',
293	      'http_proxy',
294	      'https_proxy',
295	      'no_proxy',
296	    ];
297	
298	    for (const key of authVars) {
299	      if (process.env[key]) {
300	        env[key] = process.env[key]!;
301	      }
302	    }
303	  }
304	
305	  // Merge user-configured environment variables from settings,
306	  // preventing overrides of internal keys that would break spawned processes.
307	  for (const [key, value] of Object.entries(claudeEnvVars)) {
308	    if (!RESERVED_ENV_KEYS.has(key)) {
309	      env[key] = value;
310	    }
311	  }
312	
313	  // Merge per-task port env vars (FRONTEND_PORT=…, etc) so commands run by
314	  // Claude resolve the same host port the user sees in the ports panel.
315	  // After user settings so a project never accidentally clobbers an allocated
316	  // port; before the CLAUDE_CODE_NO_FLICKER line so reserved-key checks above
317	  // would still apply if a user declared one in .dash/ports.json (the schema
318	  // enforces an allowlist regex; the RESERVED_ENV_KEYS list is a defense in
319	  // depth not really expected to fire here).
320	  if (cwd) {
321	    for (const [key, value] of Object.entries(WorkspacePortsRuntime.getEnvForWorktree(cwd))) {
322	      if (!RESERVED_ENV_KEYS.has(key)) env[key] = value;
323	    }
324	  }
325	
326	  // Disable Claude Code's built-in viewport scrolling — Dash uses its own terminal viewport
327	  env.CLAUDE_CODE_NO_FLICKER = '1';
328	
329	  // The HookServer port for this Dash session. ptyHookSettings writes hooks as
330	  // guarded curl commands that read $DASH_HOOK_PORT at runtime: present here →
331	  // they reach Dash; absent (a session the user launched outside Dash) → the
332	  // `[ -n … ]` guard makes them no-op instead of erroring with ECONNREFUSED.
333	  // Set last so it wins over any inherited value; only when the server is bound
334	  // (port 0 = not started — leaving the var unset keeps the guard honest).
335	  if (hookServer.port !== 0) {
336	    env.DASH_HOOK_PORT = String(hookServer.port);
337	  }
338	
339	  return env;
340	}
341	
342	/**
343	 * Prepend `dir` to a path-like string, but only if it isn't already there
344	 * (case-sensitive on Unix, case-sensitive on Windows is wrong but matches
345	 * what users actually do). Used when injecting Dash-managed binary
346	 * directories into the spawned process's PATH.
347	 */
348	function prependUnique(dir: string, basePath: string, sep: string): string {
349	  if (!basePath) return dir;
350	  const parts = basePath.split(sep);
351	  if (parts.includes(dir)) return basePath;
352	  return `${dir}${sep}${basePath}`;
353	}
354	
355	/**
356	 * Spawn Claude CLI directly (fast path, bypasses shell config).
357	 */
358	/**
359	 * Build the `claude` CLI args. Pure so the resume/name/permission policy is
360	 * unit-testable without spawning. Two load-bearing rules:
361	 *  - `--resume <id>` and `--name` are mutually exclusive. `--name` is a
362	 *    fresh-session display label (shown in `/resume` + the terminal title);
363	 *    combining it with `--resume` is undocumented (rename? ignore? new
364	 *    session?), and resume already targets the right session by id.
365	 *  - the initial prompt, when present, is always the LAST positional — CC
366	 *    auto-submits it once the trust-this-directory gate clears.
367	 */
368	export function buildClaudeArgs(opts: {
369	  resumeSessionId: string | null;
370	  name?: string;
371	  permissionMode?: PermissionMode;
372	  /** Model alias (opus|sonnet|haiku|fable). 'default'/undefined → no --model. */
373	  model?: TaskModel;
374	  initialPrompt?: string;
375	}): string[] {
376	  const args: string[] = [];
377	  if (opts.resumeSessionId) {
378	    args.push('--resume', opts.resumeSessionId);
379	  } else if (opts.name) {
380	    args.push('--name', opts.name);
381	  }
382	  if (opts.permissionMode === 'acceptEdits') {
383	    args.push('--permission-mode', 'acceptEdits');
384	  } else if (opts.permissionMode === 'bypassPermissions') {
385	    args.push('--dangerously-skip-permissions');
386	  }
387	  // Pin the starting model when the user chose a non-default one. 'default' omits
388	  // the flag so the user's own Claude Code config decides. Orthogonal to
389	  // resume/name, so it applies to both fresh and resumed sessions.
390	  if (opts.model && opts.model !== 'default') {
391	    args.push('--model', opts.model);
392	  }
393	  // ultracode is session-scoped; re-apply on every spawn so the user's toggle
394	  // effectively sticks across the sessions Dash launches. Must precede the
395	  // positional prompt below.
396	  if (ultracode) {
397	    args.push('--settings', JSON.stringify({ ultracode: true }));
398	  }
399	  if (opts.initialPrompt) {
400	    args.push(opts.initialPrompt);
401	  }
402	  return args;
403	}
404	
405	export async function startDirectPty(options: {
406	  id: string;
407	  cwd: string;
408	  cols: number;
409	  rows: number;
410	  permissionMode?: PermissionMode;
411	  /** Starting model → `claude --model <alias>`. 'default'/undefined omits it. */
412	  model?: TaskModel;
413	  isDark?: boolean;
414	  /** Task name → `claude --name` on a fresh spawn (recognizable in /resume). */
415	  name?: string;
416	  /** Registered agent adapter id to spawn. Absent → the default ('claude'), so
417	   *  pre-agent-column tasks and callers that don't thread it keep working. */
418	  agentId?: string;
419	  /** Per-task adapter config (e.g. the Hermes profile) threaded into buildSpawn. */
420	  agentProfile?: string | null;
421	  sender?: WebContents;
422	}): Promise<{
423	  reattached: boolean;
424	  isDirectSpawn: boolean;
425	  serializedState?: string;
426	}> {
427	  // Re-attach to existing PTY (e.g., after renderer reload)
428	  const existing = ptys.get(options.id);
429	  if (existing && !existing.isDirectSpawn) {
430	    // Shell PTY exists for this ID, but we need Claude — kill it first
431	    try {
432	      existing.proc.kill();
433	    } catch {
434	      /* already dead */
435	    }
436	    persistAndDisposeMirror(options.id, existing);
437	    ptys.delete(options.id);
438	  } else if (existing) {
439	    // Serialize BEFORE claiming the owner: a chunk arriving mid-serialize
440	    // lands in the mirror only (next output repaints it) — never duplicated.
441	    const serializedState = existing.mirror ? await existing.mirror.serialize() : undefined;
442	    existing.owner = options.sender || null;
443	    return { reattached: true, isDirectSpawn: true, serializedState };
444	  }
445	
446	  // Resolve the agent adapter for this task (defaults to the Claude reference
447	  // adapter). ptyManager no longer hardcodes Claude: binary discovery, arg/env
448	  // assembly, session resume, and hook wiring all route through the adapter
449	  // contract — see src/main/agents.
450	  const adapter = agentRegistry.resolve(options.agentId ?? DEFAULT_AGENT_ID);
451	  if (!adapter) {
452	    throw new Error(
453	      `No agent adapter registered for "${options.agentId ?? DEFAULT_AGENT_ID}". ` +
454	        'registerBuiltinAgents() must run during startup before any spawn.',
455	    );
456	  }
457	
458	  const binary = await adapter.resolveBinary();
459	  if (!binary) {
460	    throw new Error(adapter.missingBinaryHint ?? `${adapter.displayName} binary not found`);
461	  }
462	
463	  // Resume by the exact newest session id rather than `--continue`. Both rest
464	  // on a load-bearing invariant: each task has a unique cwd (worktree tasks by
465	  // construction; non-worktree tasks capped at one per project in
466	  // DatabaseService.saveTask / restoreTask, UI-gated in TaskModal). Pinning the
467	  // id we resolve ourselves — the same newest-mtime file SessionWatcherService
468	  // tails — makes the resumed session deterministically the one Dash is showing,
469	  // instead of delegating the pick to `--continue`'s undocumented selector. It
470	  // still follows /clear and /compact forks (each is a newer file).
471	  //
472	  // DO NOT relax the one-non-worktree-task cap without revisiting this; see git
473	  // history at 32bcdb6 for why the old SessionStart-hook pinning was removed.
474	  //
475	  // sessionDiscovery is a declared capability: an adapter without it degrades to
476	  // a fresh session (null resume) rather than a faked one.
477	  const resumeSessionId = adapter.sessionDiscovery?.resolveResumeId(options.cwd) ?? null;
478	
479	  // Pre-loaded prompt (the inlined ports-setup body). Only present for the
480	  // ports-migrate flow today; no-op for every other spawn. The adapter places
481	  // it last (CC auto-submits it after the trust gate clears).
482	  const initialPrompt = consumeInitialPrompt(options.id);
483	
484	  const spawnPlan = adapter.buildSpawn({
485	    taskId: options.id,
486	    cwd: options.cwd,
487	    binary,
488	    isDark: options.isDark ?? true,
489	    platform: process.platform,
490	    resumeSessionId,
491	    name: options.name,
492	    permissionMode: options.permissionMode,
493	    model: options.model,
494	    initialPrompt,
495	    agentProfile: options.agentProfile ?? undefined,
496	  });
497	
498	  // Hook wiring is a declared capability (Claude writes .claude/settings.local.json);
499	  // an adapter without it spawns with no Dash hooks.
500	  adapter.hooks?.writeSettings(options.cwd, options.id);
501	
502	  const pty = getPty();
503	  const proc = pty.spawn(spawnPlan.command, spawnPlan.args, {
504	    name: 'xterm-256color',
505	    cols: options.cols,
506	    rows: options.rows,
507	    cwd: spawnPlan.cwd,
508	    env: spawnPlan.env,
509	  });
510	
511	  const record: PtyRecord = {
512	    proc,
513	    cwd: options.cwd,
514	    isDirectSpawn: true,
515	    owner: options.sender || null,
516	    kind: 'agent',
517	    taskId: options.id,
518	    featureId: null,
519	    mirror: new TerminalMirror(options.cols, options.rows),
520	  };
521	
522	  ptys.set(options.id, record);
523	  activityMonitor.register(options.id, proc.pid);
524	
525	  // Forward output to renderer, replacing the Claude logo with "7" art.
526	  // The mirror receives the same filtered stream the renderer renders, so
527	  // its serialized state matches what a reattaching xterm should show.
528	  const bannerFilter = createBannerFilter((filtered: string) => {
529	    record.mirror?.write(filtered);
530	    if (record.owner && !record.owner.isDestroyed()) {
531	      record.owner.send(`pty:data:${options.id}`, filtered);
532	    }
533	  });
534	
535	  proc.onData((data: string) => {
536	    bannerFilter(data);
537	    activityMonitor.noteData(options.id);
538	    remoteControlService.onPtyData(options.id, data);
539	  });
540	
541	  proc.onExit(({ exitCode, signal }: { exitCode: number; signal?: number }) => {
542	    // Skip if this PTY was replaced by a new spawn (kill+restart on reattach)
543	    if (ptys.get(options.id) !== record) return;
544	    activityMonitor.unregister(options.id);
545	    remoteControlService.unregister(options.id);
546	    contextUsageService.unregister(options.id);
547	    if (record.owner && !record.owner.isDestroyed()) {
548	      record.owner.send(`pty:exit:${options.id}`, { exitCode, signal });
549	    }
550	    persistAndDisposeMirror(options.id, record);
551	    ptys.delete(options.id);
552	  });
553	
554	  return {
555	    reattached: false,
556	    isDirectSpawn: true,
557	  };
558	}
559	
560	/**
561	 * Spawn interactive shell (fallback path).
562	 */
563	export async function startPty(options: {
564	  id: string;
565	  cwd: string;
566	  cols: number;
567	  rows: number;
568	  sender?: WebContents;
569	}): Promise<{ reattached: boolean; isDirectSpawn: boolean; serializedState?: string }> {
570	  // Re-attach to existing PTY (e.g., after renderer reload)
571	  const existing = ptys.get(options.id);
572	  if (existing) {
573	    // Serialize BEFORE claiming the owner: a chunk arriving mid-serialize
574	    // lands in the mirror only (next output repaints it) — never duplicated.
575	    const serializedState = existing.mirror ? await existing.mirror.serialize() : undefined;
576	    existing.owner = options.sender || null;
577	    return { reattached: true, isDirectSpawn: existing.isDirectSpawn, serializedState };
578	  }
579	
580	  const pty = getPty();
581	
582	  const isWin = process.platform === 'win32';
583	  const shell = isWin ? 'powershell.exe' : process.env.SHELL || '/bin/bash';
584	  // Interactive, NOT login. The login files (.zprofile/.zlogin) add ~0.5s to
585	  // every fresh shell's first paint, and their main payload — PATH — is already
586	  // merged into process.env by fixPath() at boot (which runs `zsh -ilc`), so the
587	  // spawned shell inherits it. Skipping login trims the startup without losing PATH.
588	  const args = isWin ? ['-NoLogo'] : ['-i'];
589	
590	  // Clean environment for shell
591	  const env = { ...process.env };
592	  // Remove Electron packaging artifacts
593	  delete env.ELECTRON_RUN_AS_NODE;
594	  delete env.ELECTRON_NO_ATTACH_CONSOLE;
595	
596	  if (!isWin) {
597	    // Enable macOS zsh OSC 7 cwd reporting (sources /etc/zshrc_Apple_Terminal)
598	    if (process.platform === 'darwin') {
599	      env.TERM_PROGRAM = 'Apple_Terminal';
600	    }
601	
602	    // Inject custom prompt for zsh via ZDOTDIR
603	    if (shell.endsWith('/zsh') || shell === 'zsh') {
604	      env.ZDOTDIR = ensureShellConfig();
605	    }
606	  }
607	
608	  // Same port-env injection as direct PTYs — the terminal drawer shares the
609	  // task's worktree, so `curl localhost:$FRONTEND_PORT` should resolve there
610	  // too. RESERVED_ENV_KEYS guard is unnecessary here since we're working from
611	  // a fresh `{ ...process.env }` and the allocator's env-var allowlist already
612	  // excludes the reserved set.
613	  for (const [key, value] of Object.entries(WorkspacePortsRuntime.getEnvForWorktree(options.cwd))) {
614	    env[key] = value;
615	  }
616	
617	  const proc = pty.spawn(shell, args, {
618	    name: 'xterm-256color',
619	    cols: options.cols,
620	    rows: options.rows,
621	    cwd: options.cwd,
622	    env: env as Record<string, string>,
623	  });
624	
625	  // Shell PTY IDs follow the shape `shell:<taskId>[:N]`; parse the taskId so
626	  // task-scoped queries (listForTask, restartAllForTask) can find this PTY
627	  // without resorting to string-prefix matching on the id.
628	  const shellPrefix = 'shell:';
629	  const shellRest = options.id.startsWith(shellPrefix)
630	    ? options.id.slice(shellPrefix.length)
631	    : options.id;
632	  const shellTaskId = shellRest.split(':')[0]!;
633	
634	  const record: PtyRecord = {
635	    proc,
636	    cwd: options.cwd,
637	    isDirectSpawn: false,
638	    owner: options.sender || null,
639	    kind: 'shell',
640	    taskId: shellTaskId,
641	    featureId: null,
642	    mirror: new TerminalMirror(options.cols, options.rows),
643	  };
644	
645	  ptys.set(options.id, record);
646	  // Shell PTYs are not tracked by ActivityMonitor — only direct-spawn (Claude)
647	  // PTYs surface activity state to the renderer. The unregister() call on
648	  // shell PTY exit (below) is a no-op for unknown ids, so it's safe.
649	
650	  proc.onData((data: string) => {
651	    record.mirror?.write(data);
652	    if (record.owner && !record.owner.isDestroyed()) {
653	      record.owner.send(`pty:data:${options.id}`, data);
654	    }
655	  });
656	
657	  proc.onExit(({ exitCode, signal }: { exitCode: number; signal?: number }) => {
658	    // Skip if this PTY was replaced by a new spawn (kill+restart on reattach)
659	    if (ptys.get(options.id) !== record) return;
660	    activityMonitor.unregister(options.id);
661	    if (record.owner && !record.owner.isDestroyed()) {
662	      record.owner.send(`pty:exit:${options.id}`, { exitCode, signal });
663	    }
664	    persistAndDisposeMirror(options.id, record);
665	    ptys.delete(options.id);
666	  });
667	
668	  return { reattached: false, isDirectSpawn: false };
669	}
670	
671	/**
672	 * Enable remote control for a PTY by sending `/rc` and watching for the URL.
673	 */
674	export function sendRemoteControl(id: string): void {
675	  remoteControlService.startWatching(id);
676	  // Write command text first, then send Enter separately so Claude Code's
677	  // input handler processes the keystroke as a distinct event.
678	  writePty(id, '/rc');
679	  setTimeout(() => writePty(id, '\r'), 100);
680	}
681	
682	/**
683	 * Send data to a PTY.
684	 */
685	export function writePty(id: string, data: string): void {
686	  const record = ptys.get(id);
687	  if (record) {
688	    record.proc.write(data);
689	  }
690	}
691	
692	/**
693	 * Resize a PTY.
694	 */
695	export function resizePty(id: string, cols: number, rows: number): void {
696	  const record = ptys.get(id);
697	  if (record) {
698	    record.mirror?.resize(cols, rows);
699	    try {
700	      record.proc.resize(cols, rows);
701	    } catch {
702	      // EBADF can happen during transitions
703	    }
704	  }
705	}
706	
707	// Grace window for a SIGTERM'd child to flush and exit before we force SIGKILL.
708	const GRACEFUL_KILL_TIMEOUT_MS = 3000;
709	
710	/**
711	 * Gracefully terminate a pty's child process: send SIGTERM so it can flush and
712	 * exit cleanly, then escalate to SIGKILL only if it overstays the grace window.
713	 * Resolves once the process is gone (or was already dead).
714	 *
715	 * node-pty's bare `kill()` sends SIGHUP, which Claude Code does not trap — so
716	 * its in-memory session tail (the last several turns) was lost on every
717	 * refresh/quit, and no `--resume`/`--continue` could recover what never
718	 * reached the jsonl. SIGTERM + a wait gives Claude the chance to persist first.
719	 */
720	type KillableProc = {
721	  kill: (signal?: string) => void;
722	  onExit: (listener: (e: { exitCode: number; signal?: number }) => void) => {
723	    dispose: () => void;
724	  };
725	};
726	
727	function gracefulKillProc(proc: KillableProc, timeoutMs = GRACEFUL_KILL_TIMEOUT_MS): Promise<void> {
728	  return new Promise<void>((resolve) => {
729	    let settled = false;
730	    let timer: ReturnType<typeof setTimeout> | null = null;
731	    let disposable: { dispose: () => void } | null = null;
732	    const finish = () => {
733	      if (settled) return;
734	      settled = true;
735	      if (timer) clearTimeout(timer);
736	      try {
737	        disposable?.dispose();
738	      } catch {
739	        // listener already gone
740	      }
741	      resolve();
742	    };
743	    try {
744	      disposable = proc.onExit(() => finish());
745	    } catch {
746	      // proc doesn't expose onExit (already disposed) — rely on the timer/catch.
747	    }
748	    timer = setTimeout(() => {
749	      try {
750	        proc.kill('SIGKILL');
751	      } catch {
752	        // already dead
753	      }
754	      finish();
755	    }, timeoutMs);
756	    try {
757	      proc.kill('SIGTERM');
758	    } catch {
759	      // already dead — nothing to wait for
760	      finish();
761	    }
762	  });
763	}
764	
765	/** Detach a record from all registries and persist its mirror (shared by the
766	 *  kill paths). The map delete makes the spawn-time onExit handler a no-op. */
767	function teardownRecord(id: string, record: PtyRecord): void {
768	  ptys.delete(id);
769	  activityMonitor.unregister(id);
770	  remoteControlService.unregister(id);
771	  contextUsageService.unregister(id);
772	  // Persist before killing — restart() relies on the snapshot for visual
773	  // context when it respawns into the same id.
774	  persistAndDisposeMirror(id, record);
775	}
776	
777	function killPtyInternal(id: string): Promise<void> {
778	  const record = ptys.get(id);
779	  if (!record) return Promise.resolve();
780	  teardownRecord(id, record);
781	  return gracefulKillProc(record.proc);
782	}
783	
784	/**
785	 * Kill a specific PTY (graceful: SIGTERM → grace → SIGKILL). Fire-and-forget;
786	 * callers that must serialize a respawn against the dying process use
787	 * killPtyAwait instead.
788	 */
789	export function killPty(id: string): void {
790	  void killPtyInternal(id);
791	}
792	
793	/**
794	 * Kill a specific PTY and resolve once it has actually exited (or the grace
795	 * window elapsed). The renderer's reattach/restart paths await this before
796	 * respawning so the new `claude --resume` process never races the dying one
797	 * for the session jsonl (a brief two-writer overlap could corrupt the tail).
798	 */
799	export function killPtyAwait(id: string): Promise<void> {
800	  return killPtyInternal(id);
801	}
802	
803	/**
804	 * Kill all PTYs (on app quit). Awaits every child's graceful exit in parallel
805	 * so the bound is ~one grace window, not the sum — the before-quit handler
806	 * awaits this so the app doesn't exit before Claude flushes its session.
807	 */
808	export async function killAll(): Promise<void> {
809	  const pending: Promise<void>[] = [];
810	  for (const [id, record] of ptys) {
811	    persistAndDisposeMirror(id, record);
812	    pending.push(gracefulKillProc(record.proc));
813	  }
814	  ptys.clear();
815	  // Bulk cleanup — don't rely on onExit during shutdown
816	  activityMonitor.stop();
817	  await Promise.all(pending);
818	}
819	
820	/**
821	 * Kill all PTYs owned by a specific WebContents (on window close).
822	 * Fire-and-forget graceful kills — the app stays alive (macOS) so there's no
823	 * exit to race, but the child still gets its SIGTERM flush window.
824	 */
825	export function killByOwner(owner: WebContents): void {
826	  for (const [id, record] of ptys) {
827	    if (record.owner === owner) {
828	      teardownRecord(id, record);
829	      void gracefulKillProc(record.proc);
830	    }
831	  }
832	}
833	
834	/**
835	 * Return all PTY ids attached to `taskId`, optionally filtered by kind /
836	 * featureId. Used by SessionRegistry.restartAllForTask to find the right set
837	 * without string-prefix matching on PTY ids — which would accidentally hit
838	 * future task-bound PTYs (e.g. the ports TUI).
839	 */
840	export function listForTask(
841	  taskId: string,
842	  opts?: { kinds?: PtyKind[]; featureId?: string },
843	): string[] {
844	  const result: string[] = [];
845	  for (const [id, rec] of ptys) {
846	    if (rec.taskId !== taskId) continue;
847	    if (opts?.kinds && !opts.kinds.includes(rec.kind)) continue;
848	    if (opts?.featureId && rec.featureId !== opts.featureId) continue;
849	    result.push(id);
850	  }
851	  return result;
852	}
853	
854	/**
855	 * Spawn an arbitrary command in a PTY tagged as kind='tui'. Used by feature
856	 * orchestrators (e.g. ports onboarding) to host a side-car interactive
857	 * program inside the existing drawer tab UI without polluting agent/shell
858	 * code paths.
859	 */
860	export async function startCommandPty(options: {
861	  id: string;
862	  command: string;
863	  args: string[];
864	  cwd: string;
865	  cols: number;
866	  rows: number;
867	  env?: Record<string, string>;
868	  owner: WebContents | null;
869	  taskId: string;
870	  featureId: string;
871	  /** PTY registry kind. Side-car TUIs (default) vs user-facing service runs. */
872	  kind?: 'tui' | 'service';
873	  /**
874	   * Fires only when the process exits on its own — an explicit killPty()
875	   * removes the record first, so the guarded handler below never reaches it.
876	   * Callers that kill notify themselves; this hook covers self-death.
877	   */
878	  onExit?: (info: { exitCode: number; signal?: number }) => void;
879	}): Promise<{ reattached: boolean }> {
880	  const existing = ptys.get(options.id);
881	  if (existing) {
882	    existing.owner = options.owner;
883	    return { reattached: true };
884	  }
885	
886	  const pty = getPty();
887	  const proc = pty.spawn(options.command, options.args, {
888	    name: 'xterm-256color',
889	    cols: options.cols,
890	    rows: options.rows,
891	    cwd: options.cwd,
892	    env: { ...process.env, ...(options.env ?? {}) } as Record<string, string>,
893	  });
894	
895	  const record: PtyRecord = {
896	    proc,
897	    cwd: options.cwd,
898	    isDirectSpawn: false,
899	    owner: options.owner,
900	    kind: options.kind ?? 'tui',
901	    taskId: options.taskId,
902	    featureId: options.featureId,
903	    mirror: new TerminalMirror(options.cols, options.rows),
904	  };
905	
906	  ptys.set(options.id, record);
907	
908	  proc.onData((data: string) => {
909	    // The mirror always consumes — output emitted before any renderer
910	    // attaches (service startup banners) is recovered from its serialized
911	    // state on reattach.
912	    record.mirror?.write(data);
913	    if (record.owner && !record.owner.isDestroyed()) {
914	      record.owner.send(`pty:data:${options.id}`, data);
915	    }
916	  });
917	
918	  proc.onExit(({ exitCode, signal }: { exitCode: number; signal?: number }) => {
919	    if (ptys.get(options.id) !== record) return;
920	    if (record.owner && !record.owner.isDestroyed()) {
921	      record.owner.send(`pty:exit:${options.id}`, { exitCode, signal });
922	    }
923	    persistAndDisposeMirror(options.id, record);
924	    ptys.delete(options.id);
925	    options.onExit?.({ exitCode, signal });
926	  });
927	
928	  return { reattached: false };
929	}
930	
931	// ---------------------------------------------------------------------------
932	// Test-only hooks — not exported via any index. The Map is module-private,
933	// so unit tests need these handles to seed/clear synthetic records.
934	// ---------------------------------------------------------------------------
935	
936	export function __testReset(): void {
937	  for (const record of ptys.values()) {
938	    record.mirror?.dispose();
939	    record.mirror = null;
940	  }
941	  ptys.clear();
942	}
943	
944	export function __registerForTest(
945	  id: string,
946	  rec: { kind: PtyKind; taskId: string | null; featureId: string | null },
947	): void {
948	  ptys.set(id, {
949	    proc: null,
950	    cwd: '/tmp',
951	    isDirectSpawn: rec.kind === 'agent',
952	    owner: null,
953	    kind: rec.kind,
954	    taskId: rec.taskId,
955	    featureId: rec.featureId,
956	    mirror: null,
957	  });
958	}
